import{visualFor,atlasFrame,diagramSvg}from './visuals.js';import{endingData,ageText}from './chronicle.js';
export async function downloadLifeCard(s){const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const c=canvas.getContext('2d');c.fillStyle='#f6f2e9';c.fillRect(0,0,1080,1350);c.fillStyle='#385d45';c.font='bold 34px sans-serif';c.fillText('작은 발자국 · 한 생의 기록',64,80);const v=visualFor(s),p=v.portrait;const img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=p?p.url:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(diagramSvg(s,v.phase))});if(p){const sw=img.naturalWidth/p.columns,sh=img.naturalHeight/p.rows,sx=p.x/100*(p.columns-1)*sw,sy=p.y/100*(p.rows-1)*sh;c.drawImage(img,sx,sy,sw,sh,280,120,520,520)}else c.drawImage(img,280,120,520,520)}catch{c.fillStyle='#e7eddf';c.fillRect(280,120,520,520)}c.fillStyle='#293a31';c.font='bold 56px sans-serif';c.fillText(s.breed,64,725);c.font='30px sans-serif';c.fillText(`${s.country.name}에서 시작한 ${ageText(s.day)}`,64,785);const events=s.log.filter(e=>['walking','adopt','moving','companion-close','litter-born','aging'].includes(e.id)).slice(0,5);let y=860;c.font='26px sans-serif';for(const e of events){let line='';for(const ch of `${ageText(e.day)} · ${e.text}`){if(c.measureText(line+ch).width>940){c.fillText(line,64,y);y+=38;line='';if(y>1180)break}line+=ch}if(y>1180)break;c.fillText(line,64,y);y+=56}c.fillStyle='#73796f';c.font='22px sans-serif';c.fillText(`기억 ${s.memories.length}개 · 실제 생애 기록으로 만든 카드`,64,1290);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('카드를 만들지 못했습니다');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`small-footprints-${s.seed}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
